script:
@import url('https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&display=swap');

html { scroll-behavior: smooth; }
::selection { background: #FF7A3D; color: #050D14; }

/* reveal on scroll: armed by fathom_motion only when motion is allowed */
html.fa-js .fa-rise { opacity: 0; transform: translateY(26px); }
html.fa-js .fa-rise.fa-in {
  opacity: 1; transform: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.fa-js .fa-d2.fa-in { transition-delay: 0.1s; }
html.fa-js .fa-d3.fa-in { transition-delay: 0.2s; }
html.fa-js .fa-d4.fa-in { transition-delay: 0.3s; }

/* depth HUD: meaningless without the scroll driver */
.fa-hud { display: none; }
html.fa-js .fa-hud { display: flex; }

/* ------- the descent: a 100vh stage pinned inside a 560vh runner ------- */
/* without JS the scene is a plain section and the waypoints stack as a
   static depth itinerary; .fa-js switches on the machinery */
html.fa-js .fa-scene { height: 560vh; }
html.fa-js .fa-stage {
  position: sticky; top: 0; height: 100vh; max-width: none;
  align-items: center; justify-content: center; overflow: hidden;
}
html.fa-js .fa-layer {
  display: block; position: absolute; top: 0; left: 0;
  width: 100%; height: 100%; pointer-events: none;
}
html.fa-js .fa-water-video {
  object-fit: cover; transform: scale(1.06);
  opacity: calc(0.62 - var(--p) * 0.5);
}
html.fa-js .fa-water-a {
  background: linear-gradient(180deg, rgba(37, 111, 129, 0.6),
    rgba(10, 45, 64, 0.88));
  opacity: calc(1 - var(--p));
}
html.fa-js .fa-water-b {
  background: linear-gradient(180deg, #0A2537, #050D14);
  opacity: var(--p);
}
html.fa-js .fa-rays {
  background:
    linear-gradient(101deg, transparent 30%, rgba(255, 255, 255, 0.13) 34%, transparent 40%),
    linear-gradient(84deg, transparent 52%, rgba(255, 255, 255, 0.09) 57%, transparent 61%),
    linear-gradient(95deg, transparent 68%, rgba(255, 255, 255, 0.07) 74%, transparent 80%);
  mix-blend-mode: screen;
  opacity: calc(max(0, 0.85 - var(--p) * 2.1));
}
html.fa-js .fa-ruler {
  display: flex; flex-direction: column; gap: 248px; position: absolute;
  right: 36px; top: 50vh;
  transform: translateY(calc(var(--p) * -1876px));
}
html.fa-js .fa-bub {
  display: block; position: absolute; bottom: -40px;
  border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 999px;
  animation-name: fa-bub; animation-timing-function: linear;
  animation-iteration-count: infinite;
}
@keyframes fa-bub {
  from { transform: translateY(0); opacity: 0.7; }
  to { transform: translateY(-115vh); opacity: 0; }
}
html.fa-js .fa-wp {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  align-items: center; justify-content: center; text-align: center;
  border-width: 0; padding: 0 24px; pointer-events: none;
  opacity: 0; transform: translateY(48px);
  transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
html.fa-js .fa-wp > * { align-self: center; }
html.fa-js .fa-wp.fa-on { opacity: 1; transform: none; }
html.fa-js .fa-wp.fa-past { opacity: 0; transform: translateY(-48px); }

/* micro-interactions */
.fa-zoom img { transition: transform 1.2s cubic-bezier(0.22, 1, 0.36, 1); }
.fa-zoom:hover img { transform: scale(1.045); }
.fa-lift { transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.5s ease; }
.fa-lift:hover { transform: translateY(-6px); border-color: rgba(255, 122, 61, 0.45); }
.fa-btn { transition: background-color 0.25s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1); }
.fa-btn:hover { background-color: #FF9059; transform: translateY(-2px); }
.fa-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1px;
  transition: background-size 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.fa-ul:hover { background-size: 100% 1px; }
html.fa-js .fa-chev { animation: fa-chev 1.7s ease-in-out infinite; }
@keyframes fa-chev {
  0%, 100% { transform: translateY(0); opacity: 0.65; }
  50% { transform: translateY(7px); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
